__G7PRO8K_BIN_B64__
    chmod 755 "${BIN}.tmp"
    if command -v sha256sum >/dev/null 2>&1; then
        GOT_SHA="$(sha256sum "${BIN}.tmp" | awk '{print $1}')"
        if [ "${GOT_SHA}" != "${EXPECTED_SHA256}" ]; then
            rm -f "${BIN}.tmp"
            echo "ERROR: Binary checksum mismatch (expected ${EXPECTED_SHA256}, got ${GOT_SHA})" >&2
            exit 1
        fi
    fi
    mv -f "${BIN}.tmp" "${BIN}"
fi

# 3. Install default config.json only if user does not already have one.
if [ ! -f "${CONFIG}" ]; then
    echo "Writing default Xbox 360 config to ${CONFIG}..."
    cat > "${CONFIG}" <<'__G7PRO8K_CONFIG_JSON__'
{
  "profile": "xbox360",
  "emit_rate_hz": 1000,
  "extra_pids": [],
  "enable_rumble": true,
  "extra_buttons": {
    "l4": { "type": "key", "code": "KEY_F1" },
    "r4": { "type": "key", "code": "KEY_F2" },
    "l5": { "type": "key", "code": "KEY_F3" },
    "r5": { "type": "key", "code": "KEY_F4" }
  },
  "hid12_layout": {
    "report_id": 18,
    "min_length": 16,
    "l4": { "byte_offset": 13, "mask": 1 },
    "r4": { "byte_offset": 13, "mask": 2 },
    "l5": { "byte_offset": 13, "mask": 4 },
    "r5": { "byte_offset": 13, "mask": 8 },
    "gyro": { "byte_offset": 16, "length": 12 }
  },
  "web_ui": {
    "enabled": true,
    "bind": "127.0.0.1:8787"
  },
  "pid_file": "/data/local/tmp/g7pro8k/daemon.pid"
}
__G7PRO8K_CONFIG_JSON__
    chmod 644 "${CONFIG}"
else
    echo "Preserving existing ${CONFIG}."
fi

# 4. Install on-device control helper.
cat > "${CTL}" <<'__G7PRO8K_CTL_SH__'
#!/system/bin/sh
# On-device root helper for GameSir G7 Pro 8K daemon on AYN Odin 3 Pro (POSIX sh).
set -eu

BASE_DIR="${G7PRO8K_DIR:-/data/local/tmp/g7pro8k}"
BIN="${BASE_DIR}/g7pro8k-odin-daemon"
CONFIG="${BASE_DIR}/config.json"
PID_FILE="${BASE_DIR}/daemon.pid"
LOG_FILE="${BASE_DIR}/daemon.log"
WEB_BASE="${G7PRO8K_WEB_BASE:-http://127.0.0.1:8787}"

usage() {
    cat <<EOF
Usage: $(basename "$0") <command> [args]

Commands:
  start [xbox360|ds4]   Start daemon in background (optional profile override)
  stop                  Stop running daemon cleanly (releases virtual devices)
  status                Show daemon PID status and live Web API status if reachable
  pause                 Pause daemon via local API (releases USB & uinput)
  resume                Resume paused daemon via local API
  profile <xbox360|ds4> Restart daemon with specified profile
  probe                 Run USB descriptor probe
  doctor                Run system health & Odin 3 isolation check
  logs                  Print last 80 lines of daemon log
EOF
}

is_running() {
    if [ ! -f "${PID_FILE}" ]; then
        return 1
    fi
    pid="$(cat "${PID_FILE}" 2>/dev/null || true)"
    if [ -z "${pid}" ]; then
        return 1
    fi
    if [ -d "/proc/${pid}" ]; then
        return 0
    fi
    return 1
}

cmd_start() {
    profile_arg="${1:-}"
    if is_running; then
        echo "g7pro8k-odin-daemon is already running (pid $(cat "${PID_FILE}"))."
        exit 0
    fi
    if [ ! -x "${BIN}" ]; then
        echo "ERROR: Daemon binary not executable at ${BIN}" >&2
        exit 1
    fi
    mkdir -p "${BASE_DIR}"
    if [ -n "${profile_arg}" ]; then
        case "${profile_arg}" in
            xbox360|ds4) ;;
            *)
                echo "ERROR: profile must be 'xbox360' or 'ds4'" >&2
                exit 1
                ;;
        esac
        nohup "${BIN}" run --config "${CONFIG}" --profile "${profile_arg}" >>"${LOG_FILE}" 2>&1 &
    else
        nohup "${BIN}" run --config "${CONFIG}" >>"${LOG_FILE}" 2>&1 &
    fi
    sleep 1
    if is_running; then
        echo "Started g7pro8k-odin-daemon (pid $(cat "${PID_FILE}")). Web UI: ${WEB_BASE}"
    else
        echo "WARNING: Daemon exited early. Recent logs:" >&2
        tail -n 30 "${LOG_FILE}" 2>/dev/null || true
        exit 1
    fi
}

cmd_stop() {
    if ! is_running; then
        echo "g7pro8k-odin-daemon is not running."
        rm -f "${PID_FILE}"
        return 0
    fi
    pid="$(cat "${PID_FILE}")"
    kill -TERM "${pid}" 2>/dev/null || true
    i=0
    while [ "${i}" -lt 20 ]; do
        if [ ! -d "/proc/${pid}" ]; then
            rm -f "${PID_FILE}"
            echo "Stopped g7pro8k-odin-daemon cleanly."
            return 0
        fi
        sleep 1
        i=$((i + 1))
    done
    echo "Force-stopping pid ${pid}..."
    kill -KILL "${pid}" 2>/dev/null || true
    rm -f "${PID_FILE}"
}

cmd_status() {
    if is_running; then
        echo "Daemon: RUNNING (pid $(cat "${PID_FILE}"))"
        if command -v curl >/dev/null 2>&1; then
            curl -fsS "${WEB_BASE}/api/status" 2>/dev/null && echo "" || true
        fi
    else
        echo "Daemon: STOPPED"
        return 1
    fi
}

cmd_api_post() {
    endpoint="$1"
    if ! command -v curl >/dev/null 2>&1; then
        echo "ERROR: curl is required for API control; use the Web UI at ${WEB_BASE}" >&2
        exit 1
    fi
    curl -fsS -X POST "${WEB_BASE}${endpoint}" && echo ""
}

case "${1:-}" in
    start)
        cmd_start "${2:-}"
        ;;
    stop)
        cmd_stop
        ;;
    status)
        cmd_status
        ;;
    pause)
        cmd_api_post "/api/daemon/pause"
        ;;
    resume)
        cmd_api_post "/api/daemon/resume"
        ;;
    profile)
        if [ -z "${2:-}" ]; then
            echo "ERROR: specify profile 'xbox360' or 'ds4'" >&2
            exit 1
        fi
        cmd_stop
        cmd_start "$2"
        ;;
    probe)
        "${BIN}" probe --config "${CONFIG}"
        ;;
    doctor)
        "${BIN}" doctor --config "${CONFIG}"
        ;;
    logs)
        tail -n 80 "${LOG_FILE}" 2>/dev/null || echo "No log file at ${LOG_FILE}"
        ;;
    *)
        usage
        exit 1
        ;;
esac
__G7PRO8K_CTL_SH__
chmod 755 "${CTL}"

# Skip auto-start when running offline extraction verification (`G7PRO8K_EXTRACT_ONLY=1`).
if [ "${G7PRO8K_EXTRACT_ONLY:-0}" = "1" ]; then
    echo "Extract-only mode complete: ${BIN}"
    exit 0
fi

# 5. Start daemon cleanly detached from Odin 3 script runner stdio pipes.
echo "Starting g7pro8k-odin-daemon in background..."
if command -v setsid >/dev/null 2>&1; then
    setsid "${BIN}" run --config "${CONFIG}" </dev/null >>"${LOG_FILE}" 2>&1 &
else
    nohup "${BIN}" run --config "${CONFIG}" </dev/null >>"${LOG_FILE}" 2>&1 &
fi

sleep 1

if [ -f "${PID_FILE}" ] && [ -d "/proc/$(cat "${PID_FILE}" 2>/dev/null || echo 0)" ]; then
    PID_VAL="$(cat "${PID_FILE}")"
    echo "SUCCESS: g7pro8k-odin-daemon is running (pid ${PID_VAL})."
    echo "Companion Web App: ${WEB_URL}"
    if command -v am >/dev/null 2>&1; then
        am start --user 0 -a android.intent.action.VIEW -d "${WEB_URL}" >/dev/null 2>&1 || true
    fi
else
    echo "WARNING: Daemon did not report an active PID yet. Recent log lines:" >&2
    tail -n 30 "${LOG_FILE}" 2>/dev/null || true
    exit 1
fi
